if not data: quit()
N,M=data[0],data[1]
groups=[{} for _ in range(N+1)]
k=2
for _ in range(M):
 l,r,x=data[k:k+3]; k+=3
 d=groups[x]; d.setdefault(l,[]).append(r)
blocked=[[0]*(N+1) for _ in range(N+1)]
full=(1<<(N+1))-1
for p in range(1,N+1):
 d=groups[p]; mn=N+1
 for l in range(p,0,-1):
  for b in d.get(l,()):
   if b<mn: mn=b
  if mn<=N:
   blocked[p][l]=full ^ ((1<<mn)-1)
dp=[[0]*(N+1) for _ in range(N+2)]
for i in range(1,N+2): dp[i][i-1]=1
for length in range(1,N+1):
