import sys
MOD=998244353

def main():
 data=list(map(int,sys.stdin.buffer.read().split()))
 if not data:return
 n=data[0]; a=data[1:]
 M=max(a)
 spf=list(range(M+1))
 for p in range(2,int(M**0.5)+1):
  if spf[p]==p:
   for v in range(p*p,M+1,p):
    if spf[v]==v: spf[v]=p
 phi=list(range(M+1))
 for p in range(2,M+1):
  if spf[p]==p:
   for v in range(p,M+1,p): phi[v]-=phi[v]//p
 sums=[0]*(M+1)
 out=[]; ans=0; weight=1
 for x in a:
  factors=[]; y=x
  while y>1:
   p=spf[y]; e=0
   while y%p==0:
    y//=p;e+=1
   factors.append((p,e))
  divs=[1]
  for p,e in factors:
   old=divs[:]; mul=1
   for _ in range(e):
    mul*=p
    divs.extend(d*mul for d in old)
  add=0
  for d in divs: add+=phi[d]*sums[d]
  ans=(2*ans+add)%MOD
  out.append(str(ans))
  for d in divs: sums[d]=(sums[d]+weight)%MOD
  weight=weight*2%MOD
 sys.stdout.write('\n'.join(out))

if __name__=='__main__': main()

