from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        first = (0, -1)
        second = (0, -2)
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for item in by_right[r]:
                if item[0] > first[0]:
                    second = first
                    first = item
                elif item[0] > second[0]:
                    second = item

            base += r - first[0]
            if first[1] >= 0 and first[0] > second[0]:
                gains[first[1]] += first[0] - second[0]

        return base + max(gains, default=0)

