import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a-1, b-1, c)
    queries = []
    closed = [False] * M
    for _ in range(Q):
        q = list(map(int, input().split()))
        if q[0] == 1:
            i = q[1]-1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, q[1]-1, q[2]-1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            dist[a][b] = dist[b][a] = c

    for k in range(N):
        dk = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(N):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v

    answers = []
    for q in reversed(queries):
        if q[0] == 2:
            d = dist[q[1]][q[2]]
            answers.append(str(d if d < INF else -1))
        else:
            a, b, c = edges[q[1]]
            col_a = [dist[i][a] for i in range(N)]
            col_b = [dist[i][b] for i in range(N)]
            row_a = dist[a][:]
            row_b = dist[b][:]
            for i in range(N):
                da, db = col_a[i], col_b[i]
                via_ab = da + c
                via_ba = db + c
                di = dist[i]
                for j in range(i, N):
                    v = min(di[j], via_ab + row_b[j], via_ba + row_a[j])
                    if v < di[j]:
                        di[j] = v
                        dist[j][i] = v
    print('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

