import sys
sys.setrecursionlimit(1_000_000)

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=data[1:]
    pref=[0]*n; seen=set(); c=0
    for x in range(n):
        if a[x] not in seen: seen.add(a[x]); c+=1
        pref[x]=c
    suff=[0]*n; seen=set(); c=0
    for x in range(n-1,-1,-1):
        if a[x] not in seen: seen.add(a[x]); c+=1
        suff[x]=c
    size=1
    while size<n: size*=2
    neg=-10**9
    tree=[neg]*(2*size); lazy=[0]*(2*size)
    def apply(v,d):
        tree[v]+=d; lazy[v]+=d
    def push(v):
        d=lazy[v]
        if d:
            apply(v*2,d); apply(v*2+1,d); lazy[v]=0
    def add(v,l,r,ql,qr,d):
        if ql<=l and r<=qr:
            apply(v,d); return
        push(v); m=(l+r)//2
        if ql<=m: add(v*2,l,m,ql,qr,d)
        if qr>m: add(v*2+1,m+1,r,ql,qr,d)
        tree[v]=max(tree[v*2],tree[v*2+1])
    def setpoint(v,l,r,p,val):
        if l==r:
            tree[v]=val; lazy[v]=0; return
        push(v); m=(l+r)//2
        if p<=m: setpoint(v*2,l,m,p,val)
        else: setpoint(v*2+1,m+1,r,p,val)
        tree[v]=max(tree[v*2],tree[v*2+1])
    last=[0]*(n+1)
    ans=0
    for j in range(2,n):
        p=last[a[j-1]]
        lo=max(1,p); hi=j-2
        if lo<=hi: add(1,0,size-1,lo,hi,1)
        i=j-1
        setpoint(1,0,size-1,i,pref[i-1]+1)
        ans=max(ans,tree[1]+suff[j])
        last[a[j-1]]=j
    print(ans)

