import sys, math

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    values = data[2:]
    processes = [tuple(values[4*i:4*i+4]) for i in range(n)]

    def minimum_cost(target, a, p, b, q):
        g = math.gcd(a, b)
        if a * q >= b * p:  # A has at least as much capacity per yen
            # Any A/g units of B can be replaced by B/g units of A.
            limit = min(a // g, (target + b - 1) // b + 1)
            best = 10**30
            for count_b in range(limit):
                count_a = max(0, (target - b * count_b + a - 1) // a)
                best = min(best, count_a * p + count_b * q)
            return best
        else:
            limit = min(b // g, (target + a - 1) // a + 1)
            best = 10**30
            for count_a in range(limit):
                count_b = max(0, (target - a * count_a + b - 1) // b)
                best = min(best, count_a * p + count_b * q)
            return best

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            total += minimum_cost(target, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 1_000_000_001
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

