def solve():
    data=sys.stdin.buffer.read().split()
    n=int(data[0]); rows=[x.decode() for x in data[1:1+n]]
    if all(ch!='-' for row in rows for ch in row):
        print('\n'.join(' '.join('0' if i==j else '1' for j in range(n)) for i in range(n))); return
    incoming=[[[] for _ in range(26)] for _ in range(n)]
    outgoing=[[[] for _ in range(26)] for _ in range(n)]
    for x,row in enumerate(rows):
        for y,ch in enumerate(row):
            if ch!='-':
                c=ord(ch)-97
                outgoing[x][c].append(y); incoming[y][c].append(x)
    inf=10**9
    d=[[inf]*n for _ in range(n)]
    pq=[]
    for i in range(n):
        d[i][i]=0; heapq.heappush(pq,(0,i,i))
        for j,ch in enumerate(rows[i]):
            if ch!='-' and d[i][j]>1:
                d[i][j]=1; heapq.heappush(pq,(1,i,j))
    while pq:
        cost,u,v=heapq.heappop(pq)
        if cost!=d[u][v]: continue
        nd=cost+2
        for c in range(26):
            xs=incoming[u][c]; ys=outgoing[v][c]
            if not xs or not ys: continue
            for x in xs:
                dx=d[x]
                for y in ys:
                    if nd<dx[y]:
                        dx[y]=nd; heapq.heappush(pq,(nd,x,y))
    print('\n'.join(' '.join('-1' if x==inf else str(x) for x in row) for row in d))
