        return True

    left, right = 0, min(u + d for u, d in zip(U, D)) + 1
    while left + 1 < right:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    print(sum(U) + sum(D) - n * left)

