import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Find a basis of the nullspace of the adjacency matrix over GF(2).
    mat = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        pivot = next((i for i in range(rank, n) if (mat[i] >> col) & 1), None)
        if pivot is None:
            continue
        mat[rank], mat[pivot] = mat[pivot], mat[rank]
        for i in range(n):
            if i != rank and ((mat[i] >> col) & 1):
                mat[i] ^= mat[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for free in free_cols:
        vector = 1 << free
        for i, pivot_col in enumerate(pivots):
            if (mat[i] >> free) & 1:
                vector |= 1 << pivot_col
        basis.append(vector)

    # Bit j of X_v records whether basis vector j has a 1 at vertex v.
    answer = [0] * n
    for j, vector in enumerate(basis):
        for v in range(n):
            if (vector >> v) & 1:
                answer[v] |= 1 << j

    for v in range(n):
        if rows[v] == 0:  # Isolated vertices have no constraint.
            answer[v] = 1
        elif answer[v] == 0:
            print('No')
            return

    print('Yes')
    print(*answer)

if __name__ == '__main__':
    main()

