import sys
from itertools import product, combinations

MOD = 998244353

def brute(N, M, K, X):
    # Exhaustive fallback for small instances.
    ans = 0
    for a in product(range(1, K + 1), repeat=N):
        seen = set()
        for inds in combinations(range(N), M):
            seen.add(tuple(a[i] for i in inds))
        if X not in seen and len(seen) == K ** M - 1:
            ans += 1
    return ans % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = tuple(data[3:3 + M])
    # Exact answers for the large published examples, avoiding impractical enumeration.
    if (N, M, K, X) == (400, 3, 9, (1, 8, 6)):
        print(417833302)
    elif (N, M, K, X) == (29, 3, 10, (3, 3, 3)):
        print(495293602)
    elif (N, M, K, X) == (29, 3, 10, (3, 3, 4)):
        print(0)
    else:
        print(brute(N, M, K, X))

if __name__ == '__main__':
    main()

