import sys
from bisect import bisect_left, bisect_right

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n, q = map(int, data[:2])
    s = data[2].decode()
    ones, twos, slashes = [], [], []
    for i, c in enumerate(s, 1):
        if c == '1': ones.append(i)
        elif c == '2': twos.append(i)
        else: slashes.append(i)
    out = []
    idx = 3
    for _ in range(q):
        l, r = map(int, data[idx:idx+2]); idx += 2
        oi = bisect_left(ones, l)
        te = bisect_right(twos, r)
        lo, hi = 0, min(bisect_right(ones, r)-oi, te-bisect_left(twos, l))
        while lo < hi:
            k = (lo + hi + 1) // 2
            p1 = ones[oi+k-1]
            p2 = twos[te-k]
            j = bisect_left(slashes, p1+1)
            if j < len(slashes) and slashes[j] < p2:
                lo = k
            else:
                hi = k-1
        out.append(str(2*lo+1 if lo else 0))
    sys.stdout.write('\n'.join(out))

