   cols=range(m-1,-1,-1) if dc>0 else range(m)
   orders.append((rows,cols))
  for d,(dr,dc) in enumerate(dirs):
   rows,cols=orders[d]
   for r in rows:
    for c in cols:
     x=grid[r][c]
     if x not in (0,2): continue
     nr,nc=r+dr,c+dc
