      if grid[nr][nc] in (0,2) and grid[nr][nc]!=x:
       run[d][idx]=1+run[d][ni]
       best[d][idx]=1+max(run[d][ni],best[d][ni],run[(d+1)%4][ni])
      else: run[d][idx]=best[d][idx]=1
