import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        nums = list(range(1, n + 1))

        def ways(o, e, next_parity):
            m = o + e
            need_next = (m + 1) // 2
            need_other = m // 2
            if next_parity == 1:
                if o != need_next or e != need_other:
                    return 0
            else:
                if e != need_next or o != need_other:
                    return 0
            return math.factorial(o) * math.factorial(e)

        ans = []
        prev = None
        while nums:
