class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        pw = [1] * n
        for i in range(1, n):
            pw[i] = pw[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append(pw[i] if i == j else (pw[i] + pw[j]) % k)

        # suffix[i][r] says whether positions i..m-1 can contribute residue r.
        suffix = [None] * (m + 1)
        suffix[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            nxt = suffix[i + 1]
            cur = bytearray(k)
            c = coeff[i]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        cur[(r + d * c) % k] = 1
            suffix[i] = cur

        remaining = 0
        half = []
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (remaining - d * c) % k
                if suffix[i + 1][need]:
                    half.append(str(d))
                    remaining = need
                    break

        h = ''.join(half)
        if n % 2:
            return h + h[-2::-1]
        return h + h[::-1]

