class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); ng=[n]*n; st=[]
  for i in range(n-1,-1,-1):
   while st and nums[st[-1]]<=nums[i]: st.pop()
   ng[i]=st[-1] if st else n; st.append(i)
  s=[0]
  for x in nums:s.append(s[-1]+x)
  levels=n.bit_length(); jump=[array('i', ng)]; agg=[array('q', [(nums[i]*(min(ng[i],n)-i)-(s[min(ng[i],n)]-s[i])) for i in range(n)])]
  for b in range(1,levels):
   pj=jump[-1]; pa=agg[-1]; jj=array('i',[n])*n; aa=array('q',[0])*n
   for i in range(n):
    m=pj[i]
    if m<n: jj[i]=pj[m]; aa[i]=pa[i]+pa[m]
   jump.append(jj); agg.append(aa)
  def cost(l,r):
   cur=l; ans=0
   for b in range(levels-1,-1,-1):
    dest=jump[b][cur]
    if dest<=r:
     ans+=agg[b][cur]; cur=dest
   ans+=nums[cur]*(r-cur+1)-(s[r+1]-s[cur])
   return ans
  total=0
  for r in range(n):
   lo,hi=0,r+1
   while lo<hi:
    mid=(lo+hi)//2
    if cost(mid,r)<=k: hi=mid
    else:lo=mid+1
   total+=r-lo+1
  return total
